const D37 = [
{ id:'sunday-roast', c:'eu', lat:53.960, lon:-1.081, base:6, prep:30, cook:120, diff:2, tags:['beef','sunday','slow'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#8f3b2a','#e8d8b8','#c9a878','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Rôti du dimanche et Yorkshire pudding',en:'Sunday roast with Yorkshire pudding'},
  p:{fr:'York, Yorkshire, Angleterre',en:'York, Yorkshire, England'},
  d:{fr:"Le rituel dominical anglais : un rôti de bœuf, des pommes de terre rôties dans la graisse, et ces popovers qui gonflent au four. Le Yorkshire pudding se servait autrefois en entrée, arrosé de jus, pour caler les convives avant la viande.",
     en:"The English Sunday ritual: a beef roast, potatoes crisped in the fat, and those popovers that billow in the oven. Yorkshire pudding was once served first, drenched in gravy, to fill people up before the meat."},
  i:[['beef_sirloin',1.8,'kg'],['flour',150,'g'],['egg',4,'pc'],['whole_milk',250,'ml'],['beef_tallow',100,'g'],['potato',1.2,'kg'],['carrot',4,'pc'],['parsnip',3,'pc'],['onion',2,'pc'],['red_wine',200,'ml'],['beef_broth',500,'ml'],['horseradish',3,'tbsp'],['mustard',2,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Sortez le rôti deux heures à l'avance, frottez-le de moutarde, de sel et de poivre.","Saisissez-le à 240 °C pendant 20 minutes, puis baissez à 180 °C et comptez 15 minutes par 500 g pour une cuisson saignante.","Préparez la pâte à Yorkshire : farine, œufs, lait, sel, fouettés puis reposés une heure. Elle doit être fluide comme une crème.","Faites fumer la graisse de bœuf dans les moules à 220 °C, versez la pâte d'un coup et n'ouvrez pas le four pendant 20 minutes.","Laissez reposer la viande 20 minutes, déglacez le plat au vin rouge et au bouillon pour la sauce, et servez avec les légumes rôtis et le raifort."],
     en:["Take the joint out two hours ahead and rub it with mustard, salt and pepper.","Sear it at 240°C for 20 minutes, then drop to 180°C and allow 15 minutes per 500 g for rare.","Make the Yorkshire batter: flour, eggs, milk and salt, whisked then rested for an hour. It should run like cream.","Get the beef dripping smoking in the tins at 220°C, pour the batter in all at once and do not open the oven for 20 minutes.","Rest the meat for 20 minutes, deglaze the roasting tin with red wine and broth for the gravy, and serve with the roast vegetables and horseradish."]} },

{ id:'cornish-pasty', c:'eu', lat:50.263, lon:-5.051, base:4, prep:45, cook:55, diff:2, tags:['beef','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f2e6c8',style:'pastry',food:['#e0b45a','#c98a2c','#f2dfa8','#8f6a4a'],garnish:'#7fae6a'},
  n:{fr:'Cornish pasty',en:'Cornish pasty'},
  p:{fr:'Truro, Cornouailles, Angleterre',en:'Truro, Cornwall, England'},
  d:{fr:"Le chausson des mineurs d'étain, dont le bourrelet tressé servait de poignée : on le tenait par là avec des doigts pleins d'arsenic, et on jetait la crête. Bœuf, pomme de terre, rutabaga et oignon, jamais cuits à l'avance.",
     en:"The tin miners' pasty, whose plaited crimp served as a handle: held there with arsenic-covered fingers, the crest then thrown away. Beef, potato, swede and onion, never pre-cooked."},
  i:[['flour',500,'g'],['beef_suet',125,'g'],['butter',125,'g'],['ice_water',150,'ml'],['beef_skirt',400,'g'],['potato',400,'g'],['swede',200,'g'],['onion',1,'pc'],['egg',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Sablez la farine avec la graisse de bœuf et le beurre froids, ajoutez l'eau glacée et rassemblez sans pétrir. Réservez une heure au froid.","Taillez le bœuf, la pomme de terre, le rutabaga et l'oignon en dés d'un demi-centimètre — jamais râpés, jamais hachés.","Assaisonnez très généreusement de poivre blanc : c'est l'épice signature du pasty.","Découpez des disques de 20 cm, garnissez une moitié en couches, posez une noisette de beurre et repliez.","Tressez le bord en le pinçant et en le repliant sur lui-même, dorez à l'œuf, percez une cheminée et enfournez 15 minutes à 220 °C puis 40 minutes à 170 °C."],
     en:["Rub the cold suet and butter into the flour, add the iced water and bring together without kneading. Chill for an hour.","Cut the beef, potato, swede and onion into half-centimetre dice — never grated, never minced.","Season very generously with white pepper: it is the pasty's signature spice.","Cut 20 cm discs, fill one half in layers, add a knob of butter and fold over.","Crimp the edge by pinching and folding it back on itself, glaze with egg, cut a vent and bake 15 minutes at 220°C then 40 minutes at 170°C."]} },

{ id:'shepherds-pie', c:'eu', lat:53.481, lon:-2.242, base:6, prep:35, cook:70, diff:1, tags:['lamb','comfort','bake'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#e0b45a','#6f4a2a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Shepherd’s pie',en:'Shepherd’s pie'},
  p:{fr:'Manchester, Angleterre',en:'Manchester, England'},
  d:{fr:"De l'agneau haché sous une couverture de purée dorée à la fourchette. Le nom compte : au bœuf, ce serait un cottage pie — les bergers gardent des moutons, la nuance n'a rien d'un pédantisme en Angleterre.",
     en:"Minced lamb under a blanket of mashed potato forked into ridges. The name matters: made with beef it would be a cottage pie — shepherds keep sheep, and in England the distinction is no pedantry."},
  i:[['ground_lamb',800,'g'],['onion',2,'pc'],['carrot',3,'pc'],['celery',2,'stalk'],['tomato_paste',3,'tbsp'],['worcestershire',2,'tbsp'],['beef_broth',500,'ml'],['thyme',2,'tsp'],['rosemary',1,'sprig'],['peas',200,'g'],['potato',1.2,'kg'],['butter',120,'g'],['whole_milk',150,'ml'],['cheddar_cheese',80,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites colorer l'agneau haché par petites quantités, à feu vif, pour qu'il grille au lieu de bouillir.","Ajoutez oignon, carotte et céleri en petits dés et laissez-les fondre 10 minutes.","Incorporez le concentré de tomate, le worcestershire, les herbes et le bouillon, et laissez réduire 30 minutes à découvert.","Écrasez les pommes de terre avec le beurre et le lait chaud, en purée ferme : trop liquide, elle s'enfoncerait dans la viande.","Ajoutez les petits pois à la viande, couvrez de purée, striez à la fourchette, poudrez de cheddar et enfournez 35 minutes à 200 °C."],
     en:["Brown the minced lamb in small batches over high heat, so it grills rather than boils.","Add the onion, carrot and celery in small dice and let them soften for 10 minutes.","Stir in the tomato paste, Worcestershire sauce, herbs and broth, and reduce uncovered for 30 minutes.","Mash the potatoes with the butter and hot milk into a firm purée: too loose and it would sink into the meat.","Add the peas to the meat, cover with the mash, fork the surface into ridges, dust with cheddar and bake for 35 minutes at 200°C."]} },

{ id:'full-english-breakfast', c:'eu', lat:51.515, lon:-0.130, base:2, prep:15, cook:25, diff:1, tags:['breakfast','pork','comfort'],
  art:{v:'plate',bg:'#2f3326',plate:'#f4ecd8',style:'grill',food:['#c9402c','#e0b45a','#8f5a3a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Petit-déjeuner anglais complet',en:'Full English breakfast'},
  p:{fr:'Londres, Angleterre',en:'London, England'},
  d:{fr:"Œufs, bacon, saucisses, haricots, tomate, champignons, black pudding et toast : neuf éléments dans une seule assiette, cuits séparément et réunis brûlants. L'ordre d'assemblage fait l'objet de débats sincères.",
     en:"Eggs, bacon, sausages, beans, tomato, mushrooms, black pudding and toast: nine elements on one plate, cooked separately and brought together scalding. The order of assembly is the subject of sincere debate."},
  i:[['smoked_bacon',6,'slice'],['pork_sausage',4,'pc'],['egg',4,'pc'],['white_beans',400,'g'],['ripe_tomato',2,'pc'],['button_mushrooms',200,'g'],['blood_sausage',4,'slice'],['white_bread',4,'slice'],['butter',60,'g'],['tomato_paste',2,'tbsp'],['brown_sugar',1,'tbsp'],['worcestershire',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Commencez par les saucisses, qui demandent 15 minutes à feu moyen en les tournant régulièrement.","Ajoutez le bacon quand elles sont à mi-cuisson, puis le black pudding en tranches pour 3 minutes par face.","Faites revenir les champignons dans le gras rendu et les tomates coupées en deux, face contre la poêle.","Réchauffez les haricots avec le concentré, le sucre roux et le worcestershire — c'est ce qui les rapproche du goût industriel.","Faites frire les œufs en dernier, dans le gras de bacon, et faites griller le pain. Dressez sans attendre : le froid est l'ennemi du plat."],
     en:["Start with the sausages, which need 15 minutes over medium heat, turned regularly.","Add the bacon when they are half done, then the sliced black pudding for 3 minutes a side.","Fry the mushrooms in the rendered fat, and the halved tomatoes cut side down.","Warm the beans with the tomato paste, brown sugar and Worcestershire — that is what brings them close to the tinned flavour.","Fry the eggs last, in the bacon fat, and toast the bread. Plate immediately: cold is the enemy of this dish."]} },

{ id:'bakewell-tart', c:'eu', lat:53.214, lon:-1.675, base:8, prep:45, cook:45, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#8f1a3a','#f4f0e6','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Tarte de Bakewell',en:'Bakewell tart'},
  p:{fr:'Bakewell, Derbyshire, Angleterre',en:'Bakewell, Derbyshire, England'},
  d:{fr:"Une pâte sablée, une couche de confiture de framboise, une frangipane et des amandes effilées. Née, dit-on, d'une erreur d'une cuisinière d'auberge qui aurait versé l'appareil aux amandes sur la confiture au lieu de le mêler à la pâte.",
     en:"Shortcrust, a layer of raspberry jam, frangipane and flaked almonds. Born, they say, of a mistake by an inn cook who poured the almond mixture over the jam instead of stirring it into the pastry."},
  i:[['flour',250,'g'],['butter',300,'g'],['sugar',270,'g'],['egg',4,'pc'],['almonds',200,'g'],['berry_jam',200,'g'],['almond_extract',1,'tsp'],['powdered_sugar',100,'g'],['lemon',1,'pc'],['salt',null,'']],
  s:{fr:["Sablez 250 g de farine avec 125 g de beurre froid, ajoutez 50 g de sucre, un jaune et un peu d'eau glacée ; réservez une heure.","Foncez un moule de 24 cm, piquez le fond et faites cuire à blanc 15 minutes à 180 °C.","Étalez la confiture de framboise en couche régulière sur le fond refroidi.","Battez 175 g de beurre pommade avec 175 g de sucre, incorporez trois œufs un à un, puis la poudre d'amandes et l'extrait.","Étalez la frangipane, parsemez d'amandes effilées et enfournez 30 minutes à 170 °C. Glacez au sucre et au citron une fois refroidie."],
     en:["Rub 125 g of cold butter into 250 g of flour, add 50 g of sugar, a yolk and a little iced water; chill for an hour.","Line a 24 cm tin, prick the base and blind-bake for 15 minutes at 180°C.","Spread the raspberry jam in an even layer over the cooled base.","Beat 175 g of soft butter with 175 g of sugar, work in three eggs one at a time, then the ground almonds and the extract.","Spread the frangipane, scatter flaked almonds and bake for 30 minutes at 170°C. Ice with sugar and lemon once cool."]} },

{ id:'sticky-toffee-pudding', c:'eu', lat:54.201, lon:-2.955, base:8, prep:30, cook:40, diff:2, tags:['sweet','comfort','bake'],
  art:{v:'plate',bg:'#2e2419',plate:'#f4ead4',style:'cake',food:['#6f4a2a','#8f6a4a','#f4f0e6','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Sticky toffee pudding',en:'Sticky toffee pudding'},
  p:{fr:'Cartmel, Cumbrie, Angleterre',en:'Cartmel, Cumbria, England'},
  d:{fr:"Un gâteau aux dattes noyé de sauce caramel au beurre salé, servi brûlant avec de la crème froide. Inventé dans les années 1970 dans un hôtel du Lake District, il est devenu en cinquante ans le dessert anglais le plus aimé.",
     en:"A date sponge drowned in salted butter toffee sauce, served scalding with cold cream. Invented in a Lake District hotel in the 1970s, in fifty years it has become the best-loved English pudding."},
  i:[['dates',250,'g'],['boiling_water',300,'ml'],['baking_soda',1,'tsp'],['butter',300,'g'],['brown_sugar',450,'g'],['egg',3,'pc'],['flour',250,'g'],['baking_powder',1,'tsp'],['vanilla',2,'tsp'],['heavy_cream',300,'ml'],['sea_salt',1,'tsp']],
  s:{fr:["Faites tremper les dattes dénoyautées dans l'eau bouillante avec le bicarbonate 20 minutes, puis écrasez-les grossièrement.","Battez 100 g de beurre avec 150 g de sucre roux, ajoutez les œufs un à un, puis la farine et la levure.","Incorporez les dattes et leur eau : la pâte paraîtra très liquide, c'est normal.","Enfournez 35 minutes à 180 °C dans un plat beurré.","Pour la sauce, faites fondre 200 g de beurre avec 300 g de sucre roux et la crème, laissez bouillonner 5 minutes et salez. Percez le gâteau et versez la moitié de la sauce dessus, gardez le reste pour le service."],
     en:["Soak the stoned dates in the boiling water with the bicarbonate for 20 minutes, then crush them roughly.","Beat 100 g of butter with 150 g of brown sugar, add the eggs one at a time, then the flour and baking powder.","Fold in the dates and their liquid: the batter will look very loose, which is right.","Bake for 35 minutes at 180°C in a buttered dish.","For the sauce, melt 200 g of butter with 300 g of brown sugar and the cream, boil for 5 minutes and salt it. Pierce the sponge and pour over half the sauce, keeping the rest for serving."]} },

{ id:'pie-and-mash', c:'eu', lat:51.528, lon:-0.055, base:4, prep:40, cook:60, diff:2, tags:['beef','comfort','bake'],
  art:{v:'plate',bg:'#2b2a1c',plate:'#f0e4c8',style:'pastry',food:['#e0b45a','#f0e8d0','#6f8f4a','#c9a878'],garnish:'#7fae6a'},
  n:{fr:'Pie and mash à la sauce persillée',en:'Pie and mash with liquor'},
  p:{fr:'Londres Est, Angleterre',en:'East London, England'},
  d:{fr:"Une tourte au bœuf, une purée écrasée à la spatule et une sauce verte au persil appelée « liquor », héritée du jus d'anguilles pochées. Les boutiques de l'East End servent cela sur des tables de marbre depuis 1890.",
     en:"A beef pie, mash flattened with a palette knife and a green parsley sauce called 'liquor', a survivor of the water in which eels were once poached. East End shops have served this on marble tables since 1890."},
  i:[['beef_chuck',700,'g'],['onion',2,'pc'],['beef_broth',400,'ml'],['flour',400,'g'],['beef_suet',120,'g'],['butter',150,'g'],['ice_water',120,'ml'],['potato',1,'kg'],['whole_milk',150,'ml'],['parsley',2,'bunch'],['white_vinegar',2,'tbsp'],['cornstarch',2,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites revenir le bœuf haché grossièrement au couteau avec l'oignon, mouillez de bouillon et laissez mijoter 45 minutes jusqu'à ce qu'il n'y ait presque plus de liquide.","Sablez la farine avec la graisse de bœuf et le beurre, liez à l'eau glacée et réservez au froid.","Garnissez de petits moules ovales, remplissez de viande refroidie, couvrez d'un couvercle de pâte et soudez.","Enfournez 35 minutes à 200 °C, jusqu'à ce que la pâte soit blonde et ferme.","Pour le liquor, liez 400 ml d'eau de cuisson à la fécule, ajoutez une énorme quantité de persil haché et le vinaigre. Servez la purée aplatie à côté, le liquor versé sur le tout."],
     en:["Brown the beef, coarsely chopped by knife, with the onion, moisten with broth and simmer for 45 minutes until barely any liquid remains.","Rub the suet and butter into the flour, bind with iced water and chill.","Line small oval tins, fill with the cooled meat, cover with a pastry lid and seal.","Bake for 35 minutes at 200°C, until the pastry is pale gold and firm.","For the liquor, thicken 400 ml of cooking water with the cornstarch, add an enormous quantity of chopped parsley and the vinegar. Serve the flattened mash beside it, liquor poured over everything."]} },

{ id:'haggis-neeps-tatties', c:'eu', lat:55.953, lon:-3.189, base:6, prep:45, cook:180, diff:3, tags:['lamb','festive','slow'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f4a2a','#e0913a','#f0e8d0','#3a2a1a'],garnish:'#7fae6a'},
  n:{fr:'Haggis, neeps and tatties',en:'Haggis, neeps and tatties'},
  p:{fr:'Édimbourg, Écosse',en:'Edinburgh, Scotland'},
  d:{fr:"La panse de brebis farcie d'abats, d'avoine et d'oignon, servie avec purée de rutabaga et de pommes de terre. Le 25 janvier, on l'accueille en récitant l'ode que Burns lui a écrite, avant de l'ouvrir au couteau.",
     en:"A sheep's stomach stuffed with offal, oats and onion, served with mashed swede and potato. On 25 January it is piped in and addressed with the ode Burns wrote for it, before being opened with a knife."},
  i:[['sheep_pluck',1,'kg'],['pork_stomach',1,'pc'],['oats',250,'g'],['onion',3,'pc'],['lamb_fat',250,'g'],['black_peppercorns',2,'tbsp'],['nutmeg',1,'tsp'],['coriander_seeds',1,'tsp'],['swede',800,'g'],['potato',800,'g'],['butter',150,'g'],['whisky',80,'ml'],['salt',null,'']],
  s:{fr:["Faites cuire les abats 2 heures dans l'eau salée, en gardant la trachée pendante hors de la casserole. Réservez le bouillon.","Hachez-les grossièrement une fois refroidis et mêlez-les à l'avoine grillée à sec, à l'oignon haché, au gras et aux épices.","Détendez avec le bouillon jusqu'à obtenir une masse humide mais non coulante ; poivrez massivement.","Remplissez la panse aux deux tiers et cousez ; piquez-la et pochez 1 h 30 dans une eau à 85 °C.","Servez avec une purée de rutabaga au beurre, une purée de pommes de terre, et un filet de whisky versé sur le haggis ouvert."],
     en:["Simmer the pluck for 2 hours in salted water, letting the windpipe hang out of the pan. Keep the broth.","Chop it coarsely once cool and mix with the dry-toasted oats, chopped onion, fat and spices.","Loosen with the broth to a moist but not runny mass; pepper it heavily.","Fill the stomach two thirds full and sew it up; prick it and poach for 1½ hours in water at 85°C.","Serve with buttery mashed swede, mashed potato, and a thread of whisky poured over the opened haggis."]} },

{ id:'cullen-skink', c:'eu', lat:57.691, lon:-2.816, base:4, prep:20, cook:30, diff:1, tags:['sea','soup','comfort'],
  art:{v:'bowl',bg:'#26404c',plate:'#f4ecd8',style:'soup',food:['#f0e8d0','#e0b45a','#f4f0e6','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Cullen skink',en:'Cullen skink'},
  p:{fr:'Cullen, Moray, Écosse',en:'Cullen, Moray, Scotland'},
  d:{fr:"Une soupe épaisse d'églefin fumé, de pomme de terre et d'oignon, née dans le village de pêcheurs de Cullen. « Skink » désigne un jarret de bœuf en vieil écossais : c'est le nom d'un bouillon devenu, faute de viande, une soupe de poisson.",
     en:"A thick soup of smoked haddock, potato and onion, born in the fishing village of Cullen. 'Skink' means a shin of beef in old Scots: the name of a broth that became, for want of meat, a fish soup."},
  i:[['smoked_haddock',600,'g'],['potato',600,'g'],['onion',2,'pc'],['leek',1,'pc'],['whole_milk',700,'ml'],['heavy_cream',150,'ml'],['butter',60,'g'],['bay_leaf',2,'pc'],['chives',4,'tbsp'],['white_pepper',1,'tsp'],['salt',null,'']],
  s:{fr:["Pochez l'églefin fumé dans le lait avec le laurier, 8 minutes à peine, puis retirez-le et filtrez le lait.","Effeuillez la chair en gros morceaux, en éliminant peau et arêtes.","Faites fondre l'oignon et le poireau dans le beurre sans coloration, ajoutez les pommes de terre en cubes.","Mouillez du lait parfumé et laissez cuire 20 minutes ; écrasez la moitié des pommes de terre pour épaissir la soupe.","Remettez le poisson, ajoutez la crème et chauffez sans bouillir. Poivrez au poivre blanc et couvrez de ciboulette."],
     en:["Poach the smoked haddock in the milk with the bay for barely 8 minutes, then lift it out and strain the milk.","Flake the flesh into large pieces, discarding skin and bones.","Soften the onion and leek in the butter without colouring, then add the diced potatoes.","Pour in the infused milk and cook for 20 minutes; crush half the potatoes to thicken the soup.","Return the fish, add the cream and heat without boiling. Season with white pepper and cover with chives."]} },

{ id:'cranachan', c:'eu', lat:57.478, lon:-4.224, base:4, prep:20, cook:5, diff:1, tags:['sweet','fruit','fast'],
  art:{v:'glass',bg:'#2c2434',plate:'#f4ecd8',style:'cake',food:['#f4f0e6','#a8203a','#c9924a','#f0e8d0'],garnish:'#8f1a3a'},
  n:{fr:'Cranachan',en:'Cranachan'},
  p:{fr:'Inverness, Écosse',en:'Inverness, Scotland'},
  d:{fr:"Crème fouettée, framboises, miel de bruyère, whisky et avoine grillée, montés en verres. On le servait à la fête des récoltes, chaque convive mélangeant lui-même les ingrédients apportés séparément à table.",
     en:"Whipped cream, raspberries, heather honey, whisky and toasted oats, layered in glasses. Served at harvest festivals, each guest mixing for themselves from ingredients brought separately to the table."},
  i:[['oats',80,'g'],['heavy_cream',400,'ml'],['raspberries',400,'g'],['honey',80,'g'],['whisky',60,'ml'],['sugar',30,'g']],
  s:{fr:["Faites griller l'avoine à sec dans une poêle jusqu'à ce qu'elle embaume et dore, puis laissez-la refroidir complètement.","Écrasez la moitié des framboises à la fourchette avec le sucre, laissez-les rendre leur jus.","Fouettez la crème très froide en chantilly souple, sans la serrer, puis incorporez le miel et le whisky.","Ajoutez les trois quarts de l'avoine grillée à la crème et mêlez d'un geste, sans travailler.","Montez en verres en alternant crème, framboises écrasées et framboises entières. Parsemez du reste d'avoine au moment de servir, pour qu'elle reste croquante."],
     en:["Toast the oats dry in a pan until fragrant and golden, then let them cool completely.","Crush half the raspberries with a fork and the sugar, and let them give up their juice.","Whip the very cold cream to soft peaks, without tightening it, then fold in the honey and whisky.","Fold three quarters of the toasted oats into the cream in one movement, without working it.","Layer in glasses, alternating cream, crushed and whole raspberries. Scatter the remaining oats at the last moment, so they stay crisp."]} },

{ id:'scotch-broth', c:'eu', lat:55.861, lon:-4.250, base:6, prep:25, cook:120, diff:1, tags:['lamb','soup','slow'],
  art:{v:'pot',bg:'#2f3328',plate:'#f0e4c8',style:'soup',food:['#e8dcb8','#c9a24a','#7fae5a','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Scotch broth',en:'Scotch broth'},
  p:{fr:'Glasgow, Écosse',en:'Glasgow, Scotland'},
  d:{fr:"Un bouillon de mouton à l'orge perlé et aux légumes racines, si épais qu'il tient presque la cuillère. Samuel Johnson en mangea trois assiettes lors de son voyage en Écosse et admit y avoir pris goût, ce qui de sa part était beaucoup.",
     en:"A mutton broth with pearl barley and root vegetables, so thick the spoon almost stands up. Samuel Johnson ate three plates of it on his Scottish journey and admitted a liking, which from him was saying a great deal."},
  i:[['mutton_shoulder',1,'kg'],['barley',150,'g'],['split_peas',100,'g'],['carrot',3,'pc'],['swede',300,'g'],['leek',2,'pc'],['cabbage',300,'g'],['onion',2,'pc'],['parsley',5,'tbsp'],['bay_leaf',2,'pc'],['water',3,'l'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les pois cassés une nuit ; rincez l'orge perlé à l'eau claire.","Portez le mouton avec l'os à frémissement dans l'eau froide et écumez patiemment vingt minutes.","Ajoutez l'orge, les pois cassés, le laurier et l'oignon, et laissez cuire une heure à couvert.","Incorporez carotte, rutabaga et poireau en dés, puis le chou vingt minutes avant la fin.","Retirez la viande, désossez-la, remettez-la en morceaux et laissez reposer une nuit : le scotch broth est meilleur réchauffé. Poivrez et couvrez de persil."],
     en:["Soak the split peas overnight; rinse the pearl barley in cold water.","Bring the mutton on the bone to a simmer in cold water and skim patiently for twenty minutes.","Add the barley, split peas, bay and onion, and cook covered for an hour.","Stir in the diced carrot, swede and leek, then the cabbage twenty minutes before the end.","Lift out the meat, bone it, return it in pieces and rest the soup overnight: scotch broth is better reheated. Pepper it and cover with parsley."]} },

{ id:'cawl', c:'eu', lat:51.856, lon:-4.310, base:6, prep:25, cook:150, diff:1, tags:['lamb','soup','slow'],
  art:{v:'pot',bg:'#2f3328',plate:'#f0e4c8',style:'soup',food:['#e8dcb8','#7fae5a','#c9a24a','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Cawl',en:'Cawl'},
  p:{fr:'Carmarthen, Pays de Galles',en:'Carmarthen, Wales'},
  d:{fr:"Le pot-au-feu gallois : agneau, poireau, rutabaga et pomme de terre dans un bouillon clair. On le mange en deux services — le bouillon d'abord, la viande et les légumes ensuite — avec du pain et du fromage de Caerphilly.",
     en:"The Welsh pot-au-feu: lamb, leek, swede and potato in a clear broth. Eaten in two courses — broth first, meat and vegetables after — with bread and Caerphilly cheese."},
  i:[['lamb_shoulder',1.2,'kg'],['leek',4,'pc'],['swede',400,'g'],['carrot',4,'pc'],['potato',800,'g'],['parsnip',2,'pc'],['onion',2,'pc'],['bay_leaf',2,'pc'],['thyme',2,'sprig'],['parsley',5,'tbsp'],['water',3,'l'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire l'agneau avec l'os dans l'eau froide, en écumant soigneusement pendant les vingt premières minutes.","Ajoutez l'oignon, le laurier et le thym, et laissez frémir 1 h 30 sans couvrir complètement.","Laissez refroidir une nuit et retirez la graisse figée en surface : c'est ce qui donne au cawl sa clarté.","Réchauffez, ajoutez rutabaga et carotte pour 20 minutes, puis panais, pommes de terre et le blanc des poireaux pour 15 minutes.","Ajoutez le vert des poireaux en fines lanières deux minutes avant de servir, avec le persil. Servez le bouillon d'abord."],
     en:["Cook the lamb on the bone in cold water, skimming carefully for the first twenty minutes.","Add the onion, bay and thyme, and simmer for 1½ hours without fully covering.","Cool overnight and lift off the set fat: that is what gives cawl its clarity.","Reheat, add the swede and carrot for 20 minutes, then parsnip, potatoes and the white of the leeks for 15 minutes.","Add the finely shredded leek greens two minutes before serving, with the parsley. Serve the broth first."]} },

{ id:'welsh-rarebit', c:'eu', lat:51.481, lon:-3.179, base:4, prep:15, cook:10, diff:1, tags:['cheese','fast','comfort'],
  art:{v:'board',bg:'#33301f',plate:'#f0e2c0',style:'flat',food:['#e0b45a','#c98a2c','#f2dfa8','#8f6a2b'],garnish:'#7fae6a'},
  n:{fr:'Welsh rarebit',en:'Welsh rarebit'},
  p:{fr:'Cardiff, Pays de Galles',en:'Cardiff, Wales'},
  d:{fr:"Bien plus qu'un toast au fromage : une sauce épaisse de cheddar fondu à la bière brune, à la moutarde et au worcestershire, étalée sur du pain et passée au gril. Le nom se moquait des Gallois trop pauvres pour manger du lapin.",
     en:"Far more than cheese on toast: a thick sauce of cheddar melted with brown ale, mustard and Worcestershire, spread on bread and grilled. The name once mocked the Welsh as too poor to eat rabbit."},
  i:[['cheddar_cheese',400,'g'],['brown_ale',150,'ml'],['butter',40,'g'],['flour',30,'g'],['dijon_mustard',2,'tsp'],['worcestershire',2,'tsp'],['egg_yolk',2,'pc'],['rustic_bread',8,'slice'],['cayenne',1,'pinch'],['pepper',null,'']],
  s:{fr:["Faites un roux avec le beurre et la farine, puis versez la bière brune en fouettant, et laissez cuire 3 minutes.","Ajoutez le cheddar râpé hors du feu, par poignées, en remuant jusqu'à ce qu'il file.","Incorporez la moutarde, le worcestershire, le cayenne et enfin les jaunes d'œufs, sans laisser cuire.","Laissez tiédir : la pâte doit devenir assez épaisse pour s'étaler à la cuillère.","Grillez le pain d'un seul côté, étalez la pâte généreusement sur la face non grillée, jusqu'aux bords, et passez sous le gril brûlant 3 minutes jusqu'à ce qu'elle boursoufle."],
     en:["Make a roux with the butter and flour, then whisk in the brown ale and cook for 3 minutes.","Add the grated cheddar off the heat, a handful at a time, stirring until it strings.","Stir in the mustard, Worcestershire, cayenne and finally the egg yolks, without letting them cook.","Let it cool: the paste should thicken enough to spread with a spoon.","Toast the bread on one side only, spread the paste thickly right to the edges of the untoasted side, and grill fiercely for 3 minutes until it blisters."]} },

{ id:'soda-bread', c:'eu', lat:51.898, lon:-8.475, base:8, prep:10, cook:45, diff:1, tags:['bread','fast','breakfast'],
  art:{v:'board',bg:'#2f2519',plate:'#f0e2c0',style:'flat',food:['#c9a878','#e8d8b8','#8f6a4a','#f2e6c8'],garnish:'#7fae6a'},
  n:{fr:'Pain irlandais au bicarbonate',en:'Irish soda bread'},
  p:{fr:'Cork, Irlande',en:'Cork, Ireland'},
  d:{fr:"Un pain sans levure, levé par la rencontre du bicarbonate et du babeurre. Il se fait en dix minutes et se mange le jour même. La croix profonde entaillée sur le dessus laisse échapper la vapeur — et, dit-on, les mauvais esprits.",
     en:"A bread without yeast, raised by the meeting of bicarbonate and buttermilk. Made in ten minutes and eaten the same day. The deep cross cut on top lets out the steam — and, they say, the fairies."},
  i:[['whole_wheat_flour',350,'g'],['flour',150,'g'],['buttermilk',400,'ml'],['baking_soda',1,'tsp'],['oats',40,'g'],['butter',60,'g'],['honey',1,'tbsp'],['salt',null,'']],
  s:{fr:["Mêlez les farines, l'avoine, le bicarbonate et le sel dans un grand saladier, du bout des doigts.","Versez le babeurre et le miel d'un coup et mélangez à la main, en huit, pendant trente secondes seulement.","Ne pétrissez surtout pas : le bicarbonate commence à agir dès qu'il touche le babeurre et le temps vous est compté.","Formez une boule aplatie, posez-la sur une plaque farinée et entaillez une croix profonde, jusqu'à mi-hauteur.","Enfournez 45 minutes à 200 °C. Le pain est cuit quand il sonne creux dessous. Laissez refroidir sur une grille, sous un linge, pour garder une croûte tendre."],
     en:["Mix the flours, oats, bicarbonate and salt in a large bowl with your fingertips.","Pour in the buttermilk and honey all at once and mix by hand, in a figure of eight, for thirty seconds only.","Do not knead: the bicarbonate starts working the moment it meets the buttermilk and your time is short.","Shape a flattened round, set it on a floured tray and cut a deep cross, halfway down.","Bake for 45 minutes at 200°C. It is done when it sounds hollow underneath. Cool on a rack under a cloth to keep the crust soft."]} },

{ id:'colcannon', c:'eu', lat:53.270, lon:-9.057, base:4, prep:20, cook:30, diff:1, tags:['veg','comfort','festive'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ecd8',style:'stew',food:['#f0e8d0','#4f6f3a','#e0b45a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Colcannon',en:'Colcannon'},
  p:{fr:'Galway, Irlande',en:'Galway, Ireland'},
  d:{fr:"Une purée de pommes de terre au chou frisé et à l'oignon nouveau, avec un puits de beurre fondu au centre. À Halloween, on y cachait une bague : celle qui la trouvait devait se marier dans l'année.",
     en:"Mashed potato with kale and spring onion, a well of melted butter in the middle. At Halloween a ring was hidden inside: whoever found it was to marry within the year."},
  i:[['potato',1.2,'kg'],['curly_kale',400,'g'],['spring_onion',6,'pc'],['butter',150,'g'],['whole_milk',200,'ml'],['heavy_cream',100,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire les pommes de terre en robe des champs, puis épluchez-les encore chaudes en vous brûlant un peu les doigts.","Équeutez le chou frisé, hachez-le et faites-le tomber 5 minutes dans l'eau bouillante salée ; égouttez-le et pressez-le.","Faites chauffer le lait et la crème avec les oignons nouveaux émincés, sans les faire bouillir.","Écrasez les pommes de terre au presse-purée, incorporez le lait parfumé, puis le chou, et 100 g de beurre.","Dressez en dôme, creusez un puits au centre et remplissez-le du beurre restant fondu. On trempe chaque bouchée dedans."],
     en:["Boil the potatoes in their skins, then peel them while still hot, burning your fingers a little.","Strip the kale, chop it and wilt it for 5 minutes in boiling salted water; drain and squeeze it dry.","Warm the milk and cream with the sliced spring onions, without letting them boil.","Rice the potatoes, work in the infused milk, then the kale, and 100 g of butter.","Mound it up, hollow a well in the centre and fill it with the remaining melted butter. Each forkful is dipped in."]} },

{ id:'boxty', c:'eu', lat:54.033, lon:-8.067, base:4, prep:20, cook:20, diff:1, tags:['veg','fry','breakfast'],
  art:{v:'plate',bg:'#33301f',plate:'#f0e2c0',style:'flat',food:['#e8d8b8','#c9a878','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Boxty',en:'Boxty'},
  p:{fr:'Comté de Leitrim, Irlande',en:'County Leitrim, Ireland'},
  d:{fr:"La crêpe de pomme de terre du Nord-Ouest irlandais, moitié crue râpée, moitié cuite écrasée. Une comptine ancienne prévient : « Boxty on the griddle, boxty in the pan, if you can't make boxty, you'll never get a man ».",
     en:"The potato pancake of the Irish north-west, half raw and grated, half boiled and mashed. An old rhyme warns: 'Boxty on the griddle, boxty in the pan, if you can't make boxty, you'll never get a man'."},
  i:[['potato',1,'kg'],['flour',150,'g'],['buttermilk',250,'ml'],['baking_soda',1,'tsp'],['butter',80,'g'],['smoked_bacon',200,'g'],['egg',4,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire la moitié des pommes de terre et écrasez-les finement ; râpez l'autre moitié crue.","Pressez les pommes de terre râpées dans un linge au-dessus d'un bol : gardez l'eau, laissez l'amidon se déposer au fond.","Jetez l'eau claire, récupérez l'amidon blanc et ajoutez-le au mélange : c'est ce qui distingue le vrai boxty.","Mêlez les deux pommes de terre, la farine, le bicarbonate, le sel et le babeurre en une pâte épaisse.","Faites cuire de larges crêpes au beurre, 4 minutes par face. Servez avec du bacon grillé et un œuf."],
     en:["Boil half the potatoes and mash them smooth; grate the other half raw.","Squeeze the grated potato in a cloth over a bowl: keep the liquid and let the starch settle at the bottom.","Pour off the clear water, scrape up the white starch and add it to the mixture: that is what marks out real boxty.","Combine both potatoes, the flour, bicarbonate, salt and buttermilk into a thick batter.","Cook wide pancakes in butter, 4 minutes a side. Serve with grilled bacon and an egg."]} },

{ id:'bitterballen', c:'eu', lat:52.091, lon:5.121, base:6, prep:60, cook:15, diff:2, tags:['beef','fry','street'],
  art:{v:'bowl',bg:'#2f3326',plate:'#f2e6c8',style:'pastry',food:['#c98a2c','#e0b45a','#f0d89a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Bitterballen',en:'Bitterballen'},
  p:{fr:'Utrecht, Pays-Bas',en:'Utrecht, Netherlands'},
  d:{fr:"Des croquettes rondes à la sauce de bœuf figée, panées et frites, servies avec de la moutarde dans tous les cafés bruns. Le cœur est liquide et brûlant : mordre en entier est une erreur de débutant.",
     en:"Round croquettes of set beef ragout, breaded and fried, served with mustard in every brown café. The centre is liquid and scalding: biting into a whole one is a beginner's mistake."},
  i:[['beef_chuck',500,'g'],['beef_broth',700,'ml'],['butter',100,'g'],['flour',120,'g'],['onion',1,'pc'],['parsley',4,'tbsp'],['nutmeg',1,'pinch'],['egg',3,'pc'],['breadcrumbs',300,'g'],['frying_oil',1.5,'l'],['mustard',150,'g'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire le bœuf 2 heures dans le bouillon avec le laurier, jusqu'à ce qu'il s'effiloche à la fourchette. Filtrez et gardez 600 ml de bouillon.","Faites un roux avec le beurre et la farine, cuisez-le 3 minutes, puis versez le bouillon chaud en trois fois : la sauce doit devenir très épaisse.","Ajoutez la viande effilochée, l'oignon fondu, le persil et la muscade, salez généreusement.","Étalez sur 2 cm dans un plat et réfrigérez au moins 4 heures : la masse doit se couper au couteau.","Roulez des boules de 3 cm, panez deux fois à l'œuf et à la chapelure, et frites 4 minutes à 180 °C. Servez avec la moutarde."],
     en:["Cook the beef for 2 hours in the broth with the bay, until it shreds with a fork. Strain and keep 600 ml of broth.","Make a roux with the butter and flour, cook it for 3 minutes, then add the hot broth in three stages: the sauce must become very thick.","Add the shredded meat, softened onion, parsley and nutmeg, and salt generously.","Spread 2 cm deep in a dish and refrigerate for at least 4 hours: the mass should cut with a knife.","Roll 3 cm balls, bread them twice in egg and crumbs, and fry for 4 minutes at 180°C. Serve with the mustard."]} },

{ id:'hollandse-nieuwe', c:'eu', lat:52.108, lon:4.278, base:4, prep:15, cook:0, diff:1, tags:['sea','fresh','street'],
  art:{v:'board',bg:'#26384a',plate:'#f2ead6',style:'fish',food:['#e8dcc0','#f4f0e6','#6f4a5a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Hareng nouveau',en:'Hollandse nieuwe'},
  p:{fr:'Scheveningen, La Haye, Pays-Bas',en:'Scheveningen, The Hague, Netherlands'},
  d:{fr:"Le hareng de la première pêche de juin, vidé mais dont on laisse le pancréas : son enzyme fait mûrir la chair dans la saumure légère. On le mange cru, à la main, tenu par la queue et la tête renversée.",
     en:"The herring of the first June catch, gutted but with the pancreas left in: its enzyme ripens the flesh in a light brine. Eaten raw, by hand, held by the tail with the head tipped back."},
  i:[['pickled_herring',8,'pc'],['white_onion',3,'pc'],['pickles',6,'pc'],['bread_roll',4,'pc'],['butter',60,'g'],['lemon',1,'pc'],['pepper',null,'']],
  s:{fr:["Choisissez des harengs à la chair rose pâle et ferme, jamais grise : c'est le signe d'une maturation courte et correcte.","Retirez la peau en tirant de la tête vers la queue, d'un seul geste continu.","Ouvrez le hareng le long de l'arête et retirez-la en gardant les deux filets attachés à la queue.","Hachez l'oignon blanc en tout petits dés — la coutume néerlandaise, contestée par les puristes du Nord.","Servez soit à la main, tenu par la queue et trempé dans l'oignon, soit dans un petit pain beurré avec cornichons."],
     en:["Choose herring with pale pink, firm flesh, never grey: the sign of a short and proper maturation.","Remove the skin by pulling from head to tail in one continuous movement.","Open the herring along the backbone and lift it out, keeping both fillets joined at the tail.","Chop the white onion into very small dice — the Dutch custom, disputed by northern purists.","Serve either by hand, held by the tail and dipped in onion, or in a buttered roll with gherkins."]} },

{ id:'erwtensoep', c:'eu', lat:53.219, lon:6.567, base:6, prep:25, cook:180, diff:1, tags:['legume','soup','slow'],
  art:{v:'pot',bg:'#28331f',plate:'#f0e4c8',style:'soup',food:['#4f6f3a','#6f8f4a','#8f5a3a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Erwtensoep',en:'Erwtensoep'},
  p:{fr:'Groningue, Pays-Bas',en:'Groningen, Netherlands'},
  d:{fr:"La soupe de pois cassés d'hiver, si épaisse que la cuillère doit tenir debout dedans — c'est le critère officieux. On l'appelle snert, et on ne la mange qu'à partir du deuxième jour, quand elle a pris.",
     en:"The winter split pea soup, so thick the spoon must stand up in it — that is the unofficial test. It is called snert, and it is eaten only from the second day, once it has set."},
  i:[['split_peas',500,'g'],['pork_knuckle',1,'pc'],['smoked_sausage',400,'g'],['pork_belly',250,'g'],['celery_root',1,'pc'],['carrot',3,'pc'],['leek',2,'pc'],['onion',2,'pc'],['potato',400,'g'],['celery',4,'stalk'],['rye_bread',8,'slice'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les pois cassés une nuit, puis mettez-les dans trois litres d'eau froide avec le jarret et le laurier.","Portez à frémissement, écumez, et laissez cuire 1 h 30 jusqu'à ce que les pois se défassent complètement.","Ajoutez le céleri-rave, la carotte, le poireau, l'oignon et la pomme de terre en dés, et poursuivez 45 minutes.","Retirez le jarret, désossez-le, remettez la viande avec la poitrine et la saucisse fumée en rondelles pour 30 minutes.","Laissez reposer une nuit entière avant de réchauffer. Servez avec du pain de seigle beurré et de la moutarde."],
     en:["Soak the split peas overnight, then put them in three litres of cold water with the knuckle and bay.","Bring to a simmer, skim, and cook for 1½ hours until the peas have collapsed entirely.","Add the celeriac, carrot, leek, onion and potato in dice, and continue for 45 minutes.","Lift out the knuckle, bone it, return the meat with the belly and the sliced smoked sausage for 30 minutes.","Rest overnight before reheating. Serve with buttered rye bread and mustard."]} },

{ id:'poffertjes', c:'eu', lat:51.697, lon:5.304, base:6, prep:60, cook:15, diff:2, tags:['sweet','street','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#f0e0bc','#f4f0e6','#e0b45a','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Poffertjes',en:'Poffertjes'},
  p:{fr:'Bois-le-Duc, Brabant, Pays-Bas',en:'’s-Hertogenbosch, Brabant, Netherlands'},
  d:{fr:"De minuscules crêpes soufflées à la farine de sarrasin, cuites dans une plaque à alvéoles et servies sous une avalanche de sucre glace et de beurre. On les vend dans des chalets de bois sur les places, l'hiver.",
     en:"Tiny puffed pancakes made with buckwheat flour, cooked in a dimpled iron plate and served under an avalanche of icing sugar and butter. Sold from wooden chalets on the squares in winter."},
  i:[['buckwheat_flour',150,'g'],['flour',150,'g'],['whole_milk',500,'ml'],['fresh_yeast',15,'g'],['egg',2,'pc'],['butter',150,'g'],['powdered_sugar',100,'g'],['salt',null,'']],
  s:{fr:["Délayez la levure dans le lait tiède, puis fouettez avec les deux farines, les œufs et le sel.","Laissez lever une heure sous un linge : la pâte doit se couvrir de bulles et sentir la fermentation.","Beurrez généreusement chaque alvéole de la plaque et chauffez-la à feu moyen.","Remplissez les alvéoles aux trois quarts ; dès que les bords prennent, retournez chaque poffertje d'un coup de fourchette.","Comptez une minute de plus et servez aussitôt, avec une noix de beurre froid sur le dessus et beaucoup de sucre glace."],
     en:["Dissolve the yeast in the warm milk, then whisk with both flours, the eggs and the salt.","Prove for an hour under a cloth: the batter should blister and smell of fermentation.","Butter each dimple of the plate generously and heat it over medium heat.","Fill the dimples three quarters full; as soon as the edges set, flip each poffertje with a fork.","Give them another minute and serve at once, with a knob of cold butter on top and a great deal of icing sugar."]} },

{ id:'hutspot', c:'eu', lat:52.160, lon:4.491, base:6, prep:20, cook:150, diff:1, tags:['comfort','beef','slow'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#e0913a','#f0e8d0','#8f5a3a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Hutspot',en:'Hutspot'},
  p:{fr:'Leyde, Pays-Bas',en:'Leiden, Netherlands'},
  d:{fr:"Une purée de carottes, oignons et pommes de terre servie avec du bœuf braisé. La légende veut qu'un orphelin l'ait trouvée fumante dans le camp espagnol abandonné lors de la levée du siège de Leyde, le 3 octobre 1574 — on la mange encore ce jour-là.",
     en:"A mash of carrot, onion and potato served with braised beef. Legend has an orphan finding it still steaming in the abandoned Spanish camp when the siege of Leiden was lifted on 3 October 1574 — and it is still eaten on that day."},
  i:[['beef_brisket',1,'kg'],['carrot',1,'kg'],['onion',600,'g'],['potato',1,'kg'],['butter',100,'g'],['whole_milk',150,'ml'],['bay_leaf',2,'pc'],['cloves',4,'pc'],['mustard',3,'tbsp'],['vinegar',2,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire la poitrine de bœuf 2 h 30 dans l'eau salée avec le laurier et les clous de girofle, sans jamais bouillir.","Une heure avant la fin, ajoutez les carottes et les oignons en gros morceaux dans le même bouillon.","Trente minutes plus tard, ajoutez les pommes de terre.","Égouttez les légumes, écrasez-les grossièrement au presse-purée avec le beurre et un peu de bouillon : la purée doit rester rustique, avec des morceaux.","Tranchez le bœuf et servez-le sur la purée, arrosé d'un peu de bouillon, avec de la moutarde à part."],
     en:["Cook the brisket for 2½ hours in salted water with the bay and cloves, never letting it boil.","An hour before the end, add the carrots and onions in large pieces to the same broth.","Thirty minutes later, add the potatoes.","Drain the vegetables and crush them roughly with the butter and a little broth: the mash should stay rustic, with lumps.","Slice the beef and serve it on the mash, moistened with a little broth, mustard on the side."]} },

{ id:'boulets-liegeois', c:'eu', lat:50.633, lon:5.571, base:4, prep:35, cook:60, diff:2, tags:['beef','comfort','sunday'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f4a2a','#8f5a3a','#e0b45a','#c9a878'],garnish:'#7fae6a'},
  n:{fr:'Boulets à la liégeoise',en:'Liège meatballs'},
  p:{fr:'Liège, Wallonie, Belgique',en:'Liège, Wallonia, Belgium'},
  d:{fr:"De grosses boulettes de viande nappées d'une sauce lapée — sucrée-acide, au sirop de Liège, ce concentré de poires et de pommes cuit vingt heures. Servies avec des frites, elles sont l'ordinaire des friteries wallonnes.",
     en:"Large meatballs under a sauce lapée — sweet and sour, made with sirop de Liège, a concentrate of pears and apples boiled for twenty hours. Served with chips, they are the staple of Walloon friteries."},
  i:[['ground_beef',400,'g'],['ground_pork',400,'g'],['bread_roll',2,'pc'],['whole_milk',150,'ml'],['egg',2,'pc'],['onion',3,'pc'],['butter',80,'g'],['beef_broth',500,'ml'],['liege_syrup',4,'tbsp'],['cider_vinegar',3,'tbsp'],['brown_sugar',1,'tbsp'],['bay_leaf',2,'pc'],['thyme',2,'sprig'],['potato',1,'kg'],['frying_oil',1,'l'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Trempez les petits pains dans le lait, pressez-les et mêlez-les aux deux viandes, aux œufs et à un oignon râpé.","Travaillez la masse à la main 10 minutes, salez et poivrez généreusement, puis formez quatre boulettes de la taille d'un poing.","Faites-les dorer de tous côtés dans le beurre, puis réservez-les.","Faites blondir longuement les deux oignons restants émincés, mouillez de bouillon, ajoutez sirop, vinaigre, sucre, laurier et thym.","Remettez les boulets et laissez mijoter 45 minutes à couvert, en les retournant à mi-cuisson. Servez avec des frites."],
     en:["Soak the bread rolls in the milk, squeeze them out and mix with both meats, the eggs and one grated onion.","Work the mixture by hand for 10 minutes, season generously, then shape four meatballs the size of a fist.","Brown them on all sides in the butter, then set aside.","Slowly turn the two remaining sliced onions golden, moisten with broth, and add the syrup, vinegar, sugar, bay and thyme.","Return the meatballs and simmer covered for 45 minutes, turning them halfway. Serve with chips."]} },

{ id:'stoemp', c:'eu', lat:50.847, lon:4.360, base:4, prep:20, cook:35, diff:1, tags:['veg','comfort','pork'],
  art:{v:'plate',bg:'#2f3328',plate:'#f4ecd8',style:'stew',food:['#f0e8d0','#7fae5a','#e0b45a','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Stoemp',en:'Stoemp'},
  p:{fr:'Bruxelles, Belgique',en:'Brussels, Belgium'},
  d:{fr:"Une purée bruxelloise où la pomme de terre est écrasée avec un légume — carotte, poireau, chou frisé — et jamais lissée. Le mot vient du néerlandais stampen, écraser : c'est le geste qui donne son nom au plat.",
     en:"A Brussels mash in which potato is crushed with a vegetable — carrot, leek or kale — and never smoothed out. The word comes from the Dutch stampen, to crush: the gesture gives the dish its name."},
  i:[['potato',1,'kg'],['carrot',500,'g'],['leek',3,'pc'],['onion',2,'pc'],['smoked_bacon',150,'g'],['butter',100,'g'],['heavy_cream',150,'ml'],['nutmeg',1,'pinch'],['bay_leaf',2,'pc'],['pork_sausage',4,'pc'],['parsley',4,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire les pommes de terre et les carottes ensemble à l'eau salée avec le laurier, 25 minutes.","Pendant ce temps, faites fondre l'oignon émincé et le lard en dés dans la moitié du beurre, puis ajoutez les poireaux émincés et laissez-les s'attendrir 10 minutes.","Égouttez les pommes de terre et les carottes, remettez-les sur le feu deux minutes pour les assécher.","Écrasez-les grossièrement à la fourchette avec le reste de beurre, la crème et la muscade : le stoemp doit rester grumeleux.","Incorporez les poireaux et le lard, poivrez, et servez avec des saucisses poêlées et du persil."],
     en:["Boil the potatoes and carrots together in salted water with the bay for 25 minutes.","Meanwhile soften the sliced onion and diced bacon in half the butter, then add the sliced leeks and let them soften for 10 minutes.","Drain the potatoes and carrots and return them to the heat for two minutes to dry out.","Crush them roughly with a fork along with the remaining butter, the cream and the nutmeg: stoemp should stay lumpy.","Fold in the leeks and bacon, pepper it, and serve with pan-fried sausages and parsley."]} },

{ id:'waterzooi', c:'eu', lat:51.209, lon:3.224, base:6, prep:30, cook:60, diff:2, tags:['poultry','soup','comfort'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ecd8',style:'soup',food:['#f4f0e6','#e0b45a','#f0e8d0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Waterzooi de poulet',en:'Chicken waterzooi'},
  p:{fr:'Bruges, Flandre, Belgique',en:'Bruges, Flanders, Belgium'},
  d:{fr:"Un ragoût crémeux de poulet et de légumes en julienne, entre la soupe et le plat, lié au jaune d'œuf et à la crème. Il se faisait autrefois au poisson de l'Escaut ; la pollution du fleuve l'a fait passer à la volaille.",
     en:"A creamy stew of chicken and julienned vegetables, halfway between soup and main course, thickened with egg yolk and cream. Once made with fish from the Scheldt; pollution of the river turned it to poultry."},
  i:[['chicken',1.6,'kg'],['carrot',3,'pc'],['leek',3,'pc'],['celery',4,'stalk'],['celery_root',1,'pc'],['potato',600,'g'],['butter',80,'g'],['heavy_cream',300,'ml'],['egg_yolk',3,'pc'],['chicken_broth',1.5,'l'],['bay_leaf',2,'pc'],['thyme',2,'sprig'],['parsley',5,'tbsp'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites pocher le poulet entier 45 minutes dans le bouillon avec le thym et le laurier, sans bouillir.","Retirez-le, laissez-le tiédir et détachez la chair en gros morceaux ; filtrez le bouillon.","Taillez tous les légumes en fine julienne — carotte, poireau, céleri, céleri-rave — et faites-les suer au beurre 10 minutes.","Mouillez du bouillon, ajoutez les pommes de terre en bâtonnets et laissez cuire 20 minutes.","Battez les jaunes avec la crème, détendez avec une louche de bouillon chaud et incorporez hors du feu. Remettez le poulet, citronnez et couvrez de persil."],
     en:["Poach the whole chicken for 45 minutes in the broth with the thyme and bay, without boiling.","Lift it out, let it cool a little and pull the meat into large pieces; strain the broth.","Cut all the vegetables into fine julienne — carrot, leek, celery, celeriac — and sweat them in butter for 10 minutes.","Moisten with the broth, add the potatoes in batons and cook for 20 minutes.","Beat the yolks with the cream, loosen with a ladle of hot broth and stir in off the heat. Return the chicken, sharpen with lemon and cover with parsley."]} },

{ id:'anguilles-au-vert', c:'eu', lat:51.221, lon:4.400, base:4, prep:30, cook:20, diff:2, tags:['sea','fresh','sunday'],
  art:{v:'bowl',bg:'#28331f',plate:'#f2ead6',style:'fish',food:['#4f6f3a','#6f8f4a','#f0e8d0','#8fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Anguilles au vert',en:'Eels in green sauce'},
  p:{fr:'Anvers, Belgique',en:'Antwerp, Belgium'},
  d:{fr:"Des tronçons d'anguille pochés dans un bouillon d'herbes fraîches — oseille, cerfeuil, persil, estragon — qui donne à la sauce une couleur de printemps. On les mange froides ou tièdes, avec du pain et de la bière.",
     en:"Sections of eel poached in a broth of fresh herbs — sorrel, chervil, parsley, tarragon — which gives the sauce a colour of spring. Eaten cold or warm, with bread and beer."},
  i:[['eel',1,'kg'],['sorrel',200,'g'],['chervil',1,'bunch'],['parsley',1,'bunch'],['spinach',200,'g'],['mint',2,'tbsp'],['sage',6,'pc'],['butter',80,'g'],['white_wine',300,'ml'],['egg_yolk',3,'pc'],['lemon',1,'pc'],['shallot',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tronçonner l'anguille en morceaux de 5 cm par le poissonnier, peau retirée.","Faites suer les échalotes au beurre, ajoutez les tronçons et laissez-les raidir 3 minutes sans colorer.","Versez le vin blanc et autant d'eau, portez à frémissement et pochez 8 minutes.","Ajoutez toutes les herbes hachées d'un coup et laissez-les tomber 2 minutes seulement : au-delà, le vert vire au kaki.","Retirez du feu, liez avec les jaunes battus et le jus de citron, sans laisser bouillir. Laissez refroidir : le plat est meilleur frais."],
     en:["Have the fishmonger cut the eel into 5 cm sections, skin removed.","Sweat the shallots in butter, add the eel and let it firm up for 3 minutes without colouring.","Pour in the white wine and as much water again, bring to a simmer and poach for 8 minutes.","Add all the chopped herbs at once and wilt them for two minutes only: any longer and the green turns khaki.","Take off the heat, thicken with the beaten yolks and lemon juice, without boiling. Let it cool: the dish is better cold."]} },

{ id:'speculoos', c:'eu', lat:50.930, lon:5.338, base:10, prep:40, cook:15, diff:1, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#2e2419',plate:'#f2e6c8',style:'flat',food:['#8f5a2b','#c9924a','#6f4a2a','#e8d8b8'],garnish:'#c9754a'},
  n:{fr:'Spéculoos',en:'Speculoos'},
  p:{fr:'Hasselt, Limbourg, Belgique',en:'Hasselt, Limburg, Belgium'},
  d:{fr:"Le biscuit brun de la Saint-Nicolas, pressé dans des moules de bois sculptés d'images. Sa couleur ne vient pas du chocolat mais de la cassonade brune et des épices — cannelle, girofle, gingembre, cardamome, muscade.",
     en:"The brown biscuit of Saint Nicholas, pressed into wooden moulds carved with images. Its colour comes not from chocolate but from brown candi sugar and spices — cinnamon, clove, ginger, cardamom, nutmeg."},
  i:[['flour',500,'g'],['brown_sugar',300,'g'],['butter',250,'g'],['speculoos_spice',3,'tbsp'],['baking_soda',1,'tsp'],['whole_milk',60,'ml'],['almonds',80,'g'],['salt',null,'']],
  s:{fr:["Travaillez le beurre pommade avec la cassonade brune jusqu'à ce que le mélange blanchisse à peine.","Ajoutez les épices, le sel, le bicarbonate et le lait, puis la farine, et rassemblez sans pétrir.","Filmez et laissez reposer 24 heures au réfrigérateur : ce repos est indispensable, il permet aux épices de diffuser.","Étalez à 4 mm et pressez la pâte dans des moules de bois farinés, ou découpez à l'emporte-pièce.","Enfournez 15 minutes à 160 °C. Ils sont encore mous à la sortie et durcissent en refroidissant : ne prolongez pas la cuisson."],
     en:["Beat the soft butter with the brown sugar until the mixture barely lightens.","Add the spices, salt, bicarbonate and milk, then the flour, and bring together without kneading.","Wrap and rest for 24 hours in the fridge: this rest is essential, it lets the spices spread through.","Roll out to 4 mm and press the dough into floured wooden moulds, or cut with a cutter.","Bake for 15 minutes at 160°C. They are still soft when they come out and harden as they cool: do not bake them longer."]} },

{ id:'chicons-au-gratin', c:'eu', lat:50.847, lon:4.352, base:4, prep:25, cook:45, diff:1, tags:['veg','bake','cheese'],
  art:{v:'plate',bg:'#2f3326',plate:'#f4ecd8',style:'stew',food:['#f0e8d0','#e0b45a','#f4f0e6','#8fae5a'],garnish:'#7fae6a'},
  n:{fr:'Chicons au gratin',en:'Endive and ham gratin'},
  p:{fr:'Bruxelles, Belgique',en:'Brussels, Belgium'},
  d:{fr:"Des endives braisées enroulées dans du jambon et nappées de béchamel au fromage. L'endive est née à Bruxelles vers 1830, d'un agriculteur qui avait oublié des racines de chicorée dans sa cave : elles avaient blanchi.",
     en:"Braised endives wrapped in ham and covered in cheese béchamel. The endive was born in Brussels around 1830, from a farmer who forgot chicory roots in his cellar: they had blanched."},
  i:[['endive',8,'pc'],['ham',8,'slice'],['butter',100,'g'],['flour',80,'g'],['whole_milk',800,'ml'],['gruyere_cheese',200,'g'],['nutmeg',1,'pinch'],['sugar',1,'tsp'],['lemon',1,'pc'],['breadcrumbs',40,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Creusez le trognon de chaque endive au couteau pointu : c'est lui qui porte l'amertume.","Braisez-les 25 minutes dans un peu de beurre, d'eau, de sucre et de jus de citron, à couvert, en les retournant à mi-cuisson.","Égouttez-les longuement et pressez-les doucement dans un linge : toute l'eau restante détremperait le gratin.","Préparez une béchamel avec le beurre, la farine et le lait, ajoutez les trois quarts du gruyère et la muscade.","Enroulez chaque endive dans une tranche de jambon, rangez-les serrées, nappez, poudrez du reste de fromage et de chapelure, et gratinez 25 minutes à 200 °C."],
     en:["Cut out the core of each endive with a pointed knife: that is where the bitterness sits.","Braise them for 25 minutes in a little butter, water, sugar and lemon juice, covered, turning halfway.","Drain them thoroughly and press them gently in a cloth: any remaining water would flood the gratin.","Make a béchamel with the butter, flour and milk, and add three quarters of the gruyère and the nutmeg.","Wrap each endive in a slice of ham, pack them tightly, coat with the sauce, dust with the remaining cheese and breadcrumbs, and bake for 25 minutes at 200°C."]} },

{ id:'lancashire-hotpot', c:'eu', lat:53.759, lon:-2.703, base:6, prep:30, cook:180, diff:1, tags:['lamb','slow','comfort'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#e0b45a','#8f5a3a','#c9a878','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Lancashire hotpot',en:'Lancashire hotpot'},
  p:{fr:'Preston, Lancashire, Angleterre',en:'Preston, Lancashire, England'},
  d:{fr:"Des côtelettes d'agneau et des oignons sous un toit de pommes de terre en écailles, cuits trois heures sans qu'on y touche. Les ouvrières du coton le mettaient au four le matin en partant à la filature ; il les attendait le soir.",
     en:"Lamb chops and onions under a roof of overlapping potato slices, baked for three hours untouched. Cotton mill workers put it in the oven before their shift; it was waiting for them at night."},
  i:[['lamb_shoulder',1.2,'kg'],['lamb_kidney',300,'g'],['onion',600,'g'],['carrot',3,'pc'],['potato',1.2,'kg'],['flour',3,'tbsp'],['beef_broth',600,'ml'],['worcestershire',1,'tbsp'],['thyme',3,'sprig'],['bay_leaf',2,'pc'],['butter',80,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Farinez et colorez vivement les morceaux d'agneau et les rognons parés, par petites quantités.","Faites fondre les oignons \u00e9minc\u00e9s et la carotte dans la m\u00eame cocotte, en r\u00e9cup\u00e9rant les sucs.","Alternez viande et oignons dans une cocotte profonde, en assaisonnant chaque couche, puis mouillez de bouillon et de worcestershire \u00e0 mi-hauteur seulement.","Taillez les pommes de terre en rondelles de 3 mm et disposez-les en \u00e9cailles serr\u00e9es sur le dessus, en couronne, en les faisant se chevaucher.","Badigeonnez de beurre fondu, couvrez et enfournez 2 h 30 \u00e0 150 \u00b0C, puis d\u00e9couvrez 30 minutes \u00e0 200 \u00b0C pour dorer le toit."],
     en:["Flour and sear the lamb pieces and trimmed kidneys hard, in small batches.","Soften the sliced onions and carrot in the same pot, lifting the caramelised juices.","Layer meat and onions in a deep casserole, seasoning each layer, then pour in broth and Worcestershire to come only halfway up.","Slice the potatoes 3 mm thick and lay them in tight overlapping scales on top, in a spiral.","Brush with melted butter, cover and bake for 2½ hours at 150°C, then uncover for 30 minutes at 200°C to brown the roof."]} }
];

